import type {ParentToChildMessage} from '../../types.js'

export function createCallbackHandler(): {
  cancel: (callbackId: string) => void
  register: ({
    callbackId,
    name,
    timeout,
  }: {
    callbackId: string
    name: string
    timeout: number
  }) => Promise<unknown>
  handleResponse: (msg: Extract<ParentToChildMessage, {type: 'callback-response'}>) => void
}
